import {recommendedReferences,coverReference,COVER_ATLAS} from './cover-library.mjs';
import {creativeOf,newCreative,currentCover,creativeInputKey,creationErrors} from './creative.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function referenceVisual(ref){return `<span class="cover-reference-image" role="img" aria-label="${esc(ref.name)}原创参考" style="background-image:url('${COVER_ATLAS}');background-position:${(ref.cell%3)*50}% ${Math.floor(ref.cell/3)*50}%"></span>`;}
export function coverView(p){
 const stored=creativeOf(p),c=stored?.workflow===2?stored:{...newCreative(),...stored,workflow:2,candidates:[],selectedCandidateId:null},viewProject={...p,visual:{...p.visual,creative:c}},copy=c.coverCopy||{headline:'',kicker:'',points:[],benefit:''},refs=recommendedReferences(p.content.topic),ref=coverReference(c.referenceId),key=creativeInputKey(viewProject),selected=currentCover(viewProject),candidates=c.candidates||[],errors=creationErrors({...p,visual:{...p.visual,creative:c}});
 return `<div class="work-heading"><h1>封面制作</h1><button class="btn text small" data-action="library">返回内容库</button></div><p class="work-subtitle">${esc(p.content.topic)} · 先看参考，再生成候选，最后挑选成品。</p>
 <section class="cover-intro"><div><span class="cover-kicker">COVER STUDIO</span><h2>先看到喜欢的样子。</h2><p>封面可以用真人、设备、作品或文字图形。内容与内页可以独立推进。</p></div><div class="cover-progress"><span class="${c.referenceId?'done':''}">01 看参考</span><span class="${!errors.length?'done':''}">02 准备与生成</span><span class="${selected?'done':''}">03 挑选成品</span></div></section>
 <section class="cover-section"><div class="section-line"><h2>01 · 哪张参考更接近你的想法？</h2><span class="small muted">结合主题排列 · 可以随时换</span></div><p class="muted">先看构图、人物与标题的关系。示例中的人不是你的本人照片，示例文字也不会进入本期内容。</p><div class="cover-reference-grid">${refs.map((r,i)=>`<article class="cover-reference ${c.referenceId===r.id?'chosen':''}"><button class="cover-image-button" data-action="cover-reference-zoom" data-reference="${r.id}" aria-label="放大${r.name}">${referenceVisual(r)}<span class="cover-image-hint">放大查看</span></button><div class="cover-reference-copy"><div class="row between"><b>${esc(r.name)}</b>${i<2&&r.tags.some(t=>p.content.topic.includes(t))?'<span class="cover-recommended">适合本期</span>':''}</div><p>${esc(r.description)}</p><small class="cover-learn">借鉴：${esc(r.learn)}</small><button class="btn ${c.referenceId===r.id?'primary':'secondary'}" data-action="cover-reference" data-reference="${r.id}" aria-pressed="${c.referenceId===r.id}">${c.referenceId===r.id?'已选参考':'参考这张'} · ${r.mode==='portrait'?'真人示例':'无真人示例'}</button></div></article>`).join('')}</div><details class="cover-custom"><summary>我有自己的参考图</summary><label for="composition-reference">上传喜欢的封面，只参考构图与设计</label><input id="composition-reference" type="file" data-composition-upload accept="image/png,image/jpeg,image/webp">${c.reference?`<div class="cover-custom-preview"><img src="${esc(c.reference.data)}" alt="用户构图参考"><span>${esc(c.reference.name)}</span><button class="btn secondary" data-action="use-custom-reference">参考这张</button><button class="btn text" data-action="remove-composition">移除</button></div>`:''}</details><p class="small muted cover-provenance">以上为本项目原创 AI 设计示例，并非开拍官方模板。设计研究参考开拍的封面功能与视频语境，生成时重新结合主题组织画面。<a href="https://play.google.com/store/apps/details?id=com.meitu.action&hl=zh_CN" target="_blank" rel="noopener">查看研究来源 ↗</a></p></section>
 <section class="cover-section"><h2>02 · 根据参考，准备这期的画面</h2><p class="muted">${c.referenceId?`当前参考：${esc(ref?.name||'自定义构图')}。你仍可以决定是否使用真人。`:'选好上面的参考后，再准备素材。'}</p><div class="choice-row"><button data-action="cover-mode" data-mode="portrait" class="${c.mode==='portrait'?'active':''}" aria-pressed="${c.mode==='portrait'}">使用本人照片</button><button data-action="cover-mode" data-mode="text" class="${c.mode==='text'?'active':''}" aria-pressed="${c.mode==='text'}">不使用真人</button></div><details class="cover-copy" open><summary>封面要说什么？</summary><p class="small muted">主标题默认使用首图标题。引题、辅助要点和收益条可留空；只写本期能兑现的内容，不修改已确认正文。</p><div class="cover-copy-grid"><div><label for="cover-headline">主标题（可选改写）</label><textarea id="cover-headline" data-cover-copy="headline" rows="2" maxlength="300" placeholder="${esc(p.content.cards[0]?.title||p.content.topic)}">${esc(copy.headline)}</textarea><label for="cover-kicker">引题 / 对象标签（可选）</label><input id="cover-kicker" data-cover-copy="kicker" maxlength="300" value="${esc(copy.kicker)}" placeholder="例如：项目迁移 · 小白教程"></div><div><label for="cover-points">辅助要点（可选，每行一条，最多3条）</label><textarea id="cover-points" data-cover-copy="points" rows="3" placeholder="用本期真实内容填写，不从参考照搬">${esc(copy.points.join('\n'))}</textarea><label for="cover-benefit">收益条（可选）</label><input id="cover-benefit" data-cover-copy="benefit" maxlength="300" value="${esc(copy.benefit)}" placeholder="本期内容能兑现的收获"></div></div></details><div class="cover-preparation-grid"><div>${c.mode==='portrait'?`<label for="portrait-photo">本人照片 · 只用于身份</label><input id="portrait-photo" type="file" data-portrait-upload accept="image/png,image/jpeg,image/webp"><p class="small muted">脸部清晰的本人照片，PNG/JPEG/WebP，每张6MB以内。与构图参考分开保存。</p>${c.portrait?`<div class="cover-person"><img src="${esc(c.portrait.data)}" alt="已上传的身份照片"><div><b>${esc(c.portrait.name)}</b><p>生成前由 Codex 查看，确认包含可辨认真人。若沿用旧封面，仅提取人物身份，不照搬动作、服装、背景和文字。</p><button class="btn text small" data-action="remove-portrait">移除本人照片</button></div></div>`:'<div class="cover-empty">选择真人后，需要本人照片才能生成。</div>'}`:c.mode==='text'?'<div class="cover-empty">无需上传本人照片。生成时用设备、物件、作品或文字图形表达主题，不放入随机人物。</div>':'<div class="cover-empty">真人与无真人都可以；先看参考再决定。</div>'}</div><div><label for="cover-direction">想保留或调整什么？（可选）</label><textarea id="cover-direction" data-cover-direction rows="4" maxlength="3000" placeholder="例如：喜欢这个构图，但换成两台电脑；不要沿用上一期人物动作。">${esc(c.coverDirection||'')}</textarea><p class="small muted">封面偏好只影响封面，不改已确认的正文或内页配色。</p><p class="cover-status" data-cover-status>${errors.length?esc(errors.join('；')):'参考与素材已准备，可以生成候选。'}</p><button class="btn primary" data-action="cover-task" ${errors.length?'disabled':''}>复制 3 张候选的生成任务</button><p class="small muted">发到当前 Codex 对话，使用内置图片工具生成并导入。网页负责保存素材与选择。</p><label for="cover-result">已有生成结果？导入为候选</label><input id="cover-result" type="file" data-cover-result accept="image/png,image/jpeg,image/webp" ${errors.length?'disabled':''}></div></div></section>
 <details class="cover-quality"><summary>这期封面的检查标准</summary><ul><li>缩略图能看清主标题、对象和核心承诺。</li><li>人物、标题、辅助要点有关系，脸部不被遮挡；自然背景也可以有明确设计。</li><li>标签、圈线、箭头或清单承担解释；不机械添加装饰。</li><li>没有从参考照搬数字、保证、经历或成果，内容能够兑现封面。</li><li>候选改变景别、位置、场景或信息结构；系列感不等于同图换字。</li></ul></details><section class="cover-section"><div class="section-line"><h2>03 · 看成品，挑选本期封面</h2><span class="small muted">${candidates.length} / 6 张候选</span></div><p class="muted">导入不代表选中。先检查脸部、标题和构图，选中后再与整期图卡一起审核。</p>${candidates.length?`<div class="cover-candidate-grid">${candidates.map(x=>{const stale=x.inputFingerprint!==key,active=x.id===c.selectedCandidateId&&!stale;return `<article class="cover-candidate ${active?'chosen':''}"><button class="cover-image-button" data-action="cover-candidate-zoom" data-candidate="${esc(x.id)}"><img src="${esc(x.data)}" alt="${esc(x.name)}"><span class="cover-image-hint">放大检查人物与标题</span></button><div class="cover-reference-copy"><b>${esc(x.name)}</b><p>${stale?'输入已变更 · 保留作对比，需要重新生成':active?'已选为本期封面 · 尚待图卡审核':'当前输入的候选 · 等待挑选'}</p><div class="row wrap"><button class="btn ${active?'primary':'secondary'}" data-action="cover-select" data-candidate="${esc(x.id)}" ${stale?'disabled':''}>${active?'当前封面':'选为本期封面'}</button><button class="btn text small" data-action="cover-candidate-remove" data-candidate="${esc(x.id)}">移除</button></div></div></article>`;}).join('')}</div>`:`<div class="cover-empty">候选生成后会出现在这里。你可以先选参考，也可以继续编辑正文。</div>${c.result?`<details class="cover-custom"><summary>查看上一版已存封面</summary><img class="cover-previous" src="${esc(c.result.data)}" alt="上一版封面"><p class="small muted">保留已有版本；选择新参考后需要生成新的候选。</p></details>`:''}`}<div class="action-bar"><span class="small muted" data-cover-selection-status>${selected?'本期封面已选；生成与选择不代表最终审核。':'本期封面等待挑选。'}</span><button class="btn secondary" data-stage="content">继续编辑内容</button><button class="btn primary" data-stage="design" ${p.contentApproval?'':'disabled'}>查看教程内页</button></div></section>`;
}
export function coverLibrary(projects){return `<div class="page-heading"><div><div class="eyebrow">COVER STUDIO</div><h1>封面制作</h1><p>为这一期找到合适的画面。先看参考，再生成，最后挑选。</p></div><button class="btn secondary" data-action="new">新建一期内容</button></div><section class="projects-grid">${projects.map(p=>`<button class="project-tile" data-action="cover-open" data-project="${esc(p.id)}"><div class="project-cover"><div class="mini-card"><small>制作封面</small><div class="mini-title">${esc(p.content.cards[0]?.title||p.content.topic)}</div></div></div><div class="project-details"><h3>${esc(p.content.topic)}</h3><p class="small muted">${currentCover(p)?'已有封面，可继续比较与调整':'看参考 · 准备素材 · 挑选候选'}</p></div></button>`).join('')}</section>`;}
